let particles = [];

function preload() {
	theShader = getShader(this._renderer);
}

function setup() {
	createCanvas(1112, 834, WEBGL);
	createEasyCam();
	perspective(PI/3, width/height, 0.01, 500)
}

function draw() {
	background(0);
	stroke(255);
	//strokeWeight(100);
	shader(theShader);
	theShader.setUniform("uFrameCount", frameCount);

	particles.push(new particle);

	offset = 0;
	for(let i = 0; i<particles.length-offset; i++) {
		if(particles[i].age<0.01) {
			particles.splice(i, 1);
			offset++;
		}
		else
			particles[i].display();
	}
}

class particle {


	constructor() {
		this.x = 0;
		this.y = 0;
		this.z = 0;
		this.xvel = random(-1, 1);
		this.yvel = random(-0.2, 0.2);
		this.zvel = random(-1, 1);
		this.age = random(1.2, 0.7);
	}

	display() {
		this.x += this.xvel;
		this.y += this.yvel;
		this.z += this.zvel;

		this.xvel *= 0.95;
		this.zvel *= 0.95;
		this.yvel *= 0.95;
		this.yvel += 0.03;
		this.age -= 0.01;

		this.x *= 0.99;
		this.z *= 0.99;

		theShader.setUniform("uFirePos", [this.x, this.y, this.z]);
		plane(this.age*10);

	}

}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
